import json
import sqlite3
from pathlib import Path
records = json.loads(Path('/tmp/cat218-feed.json').read_text())
with sqlite3.connect('data/catalog.db') as db, sqlite3.connect('/tmp/catalog-before-cat218.db') as backup:
    current = {r[0]: r for r in db.execute('SELECT * FROM products')}
    before = {r[0]: r for r in backup.execute('SELECT * FROM products')}
    seen = {r['sku'] for r in records}
    for item in records:
        sku = item['sku']
        if before.get(sku, (None, None, None, None))[3] == 'manual':
            assert current[sku] == before[sku]
        elif item.get('deleted'):
            assert sku not in current
        else:
            assert current[sku] == (sku, item['name'], item['price_paise'], 'vendor', item['updated_at'])
    for sku, row in before.items():
        if row[3] == 'manual' or sku not in seen:
            assert current[sku] == row
    assert len(current) == 307
    assert db.execute('PRAGMA integrity_check').fetchone() == ('ok',)
    print('Verified all 260 live records, 8 tombstones, 35 unchanged manual SKUs, and 47 retained unmentioned SKUs.')
    print('Sync state:', list(db.execute('SELECT * FROM sync_state')))
